    t11_h1: "Potriviți jumătățile de propoziție.",
    t11_h2: "Deși era târziu -> am continuat să muncim.",
    t11_l1: "Deși era târziu,", t11_r1: "am continuat să muncim.",
    t11_l2: "Chiar dacă era obosit,", t11_r2: "a terminat cursa.",
    t11_q: "Care conjuncție înseamnă același lucru cu „chiar dacă”?",
    t11_c1: "deși", t11_c2: "pentru că", t11_c3: "din moment ce", t11_c4: "sau",
    t11_svg_w1: "deși",

    // T12 - "while" / "when" / "after"
    t12_title: "Conjuncții de timp",
    t12_text: "Unele conjuncții ne spun CÂND se întâmplă ceva. Exemple: în timp ce, când, după, înainte, până. — Voi aștepta până când ești gata.",
    t12_inst: "Completați cuvântul de timp care lipsește!",
    t12_h1: "Ce faci mai întâi?",
    t12_h2: "Spală-te pe dinți înainte de a merge la culcare.",
    t12_sent: "Spală-te pe dinți _______ te duci la culcare.",
    t12_c1: "înainte", t12_c2: "în timp ce", t12_c3: "deși", t12_c4: "pentru că",
    t12_q: "Care dintre acestea este o conjuncție de timp?",
    t12_qc1: "până când", t12_qc2: "pentru că", t12_qc3: "deși", t12_qc4: "dacă",
    t12_svg_w1: "când", t12_svg_w2: "în timp ce", t12_svg_w3: "după",

    // T13 - "if" / "unless"
    t13_title: "Condiții: Dacă și dacă nu",
    t13_text: "„Dacă” și „dacă nu” stabilesc o condiție. Trebuie îndeplinită o condiție pentru ca rezultatul să se întâmple. — Vei eşua dacă nu studiezi. („dacă nu” înseamnă „dacă nu”).",
    t13_inst: "Alegeți condiția corectă!",
    t13_h1: "Care cuvânt înseamnă o condiție?",
    t13_h2: "Vom merge în parc dacă nu mai plouă.",
    t13_sent: "Vom merge în parc ___ nu mai plouă.",
    t13_c1: "dacă", t13_c2: "decât dacă", t13_c3: "deși", t13_c4: "înainte",
    t13_q: "Ce înseamnă conjuncția „cu excepția cazului”?",
    t13_qc1: "dacă nu", t13_qc2: "pentru că", t13_qc3: "în timp ce", t13_qc4: "după",
    t13_svg_lbl: "Condiții",

    // T14 - Correlative conjunctions
    t14_title: "Conjuncții corelative",
    t14_text: "Conjuncțiile corelative funcționează în perechi pentru a conecta părți ale unei propoziții. Exemple: fie/sau, nici/nici, ambele/și.",
    t14_h1: "Potriviți perechile corecte împreună.",
    t14_h2: "Fie se cuplează cu sau. Nici perechi cu nici.",
