    t7_inst: "Ordne den Satz richtig!",
    t7_h1: "Beginnen Sie mit dem Interjektion „Ugh,“.",
    t7_h2: "Ugh, diese Milch ist sauer.",
    t7_w1: "Ugh,", t7_w2: "dies", t7_w3: "Milch", t7_w4: "ist", t7_w5: "sauer.",
    t7_q: "Welcher Zwischenruf drückt Ekel aus?",
    t7_c1: "Igitt!", t7_c2: "Wow!", t7_c3: "Juhuu!", t7_c4: "Puh!",
    t7_svg_w1: "Pfui!",

    // T8 - "Hooray" (Celebration)
