    t8_text: "„Hooray“, „Yay“ und „Woohoo“ werden verwendet, um extremes Glück zu feiern oder zu zeigen.",
    t8_inst: "Füllen Sie die Lücke mit dem Festwort aus!",
    t8_h1: "Welches Wort zeigt die Begeisterung für den Sieg an?",
    t8_h2: "„Hurra“ passt am besten.",
    t8_sent: "___! Morgen ist der letzte Schultag.",
    t8_c1: "Hurra", t8_c2: "Autsch", t8_c3: "Ups", t8_c4: "Leider",
    t8_q: "Welcher Interjektion drückt Feier aus?",
    t8_svg_w1: "Hurra!",

    // T9 - "Ouch" (Pain)
    t9_title: "Schmerz ausdrücken",
    t9_text: "„Autsch“ und „Au“ sind Interjektionen, mit denen plötzliche körperliche Schmerzen ausgedrückt werden.",
    t9_inst: "Markieren Sie den Zwischenruf im Satz!",
    t9_h1: "Suchen Sie nach dem Wort, das Schmerz ausdrückt.",
    t9_h2: "Markieren Sie „Au!“.",
    t9_sent: "Au! Eine Biene hat gerade meinen Arm gestochen.",
    t9_target: "Au!",
    t9_q: "Welchen Interjektion würden Sie verwenden, wenn Sie sich den Zeh stoßen würden?",
    t9_c1: "Autsch!", t9_c2: "Wow!", t9_c3: "Hey!", t9_c4: "Juhuu!",
    t9_svg_w1: "Au!", t9_svg_w2: "Autsch!",

    // T10 - "Hmm" (Thinking)
    t10_title: "Nachdenken und Zögern",
    t10_text: "Wörter wie „Hmm“, „Uh“ und „Ähm“ sind Interjektionen, die Zögern oder Nachdenken zum Ausdruck bringen.",
    t10_inst: "Ordnen Sie die Interjektionen ihrem Zweck zu!",
    t10_h1: "„Hmm“ gehört zum Denken.",
    t10_h2: "„Yay“ passt zu Celebration.",
    t10_l1: "Hm...", t10_r1: "Denken",
    t10_l2: "Juhuu!", t10_r2: "Feier",
    t10_l3: "Ew!", t10_r3: "Ekel",
    t10_q: "Welcher Zwischenruf zeigt, dass jemand nachdenkt?",
    t10_c1: "Hmm", t10_c2: "Autsch", t10_c3: "Ups", t10_c4: "Hurra",
    t10_svg_icon: "🤔", t10_svg_lbl: "Hm...",

    // T11 - Punctuation Rules
    t11_title: "Zeichensetzungsregeln",
    t11_text: "Wenn auf einen Interjektionszeichen ein Ausrufezeichen folgt, MUSS das nächste Wort mit einem Großbuchstaben beginnen. 'Autsch! „Mein Fuß tut weh.“",
    t11_inst: "Füllen Sie die Lücke mit der richtigen Groß- und Kleinschreibung aus!",
    t11_h1: "Schauen Sie sich die Interpunktion vor dem Leerzeichen an. Es ist ein Ausrufezeichen (!).",
    t11_h2: "Verwenden Sie die Großschreibung „Das“.",
    t11_sent: "Wow! ___ war ein toller Film.",
    t11_c1: "Das", t11_c2: "das", t11_c3: "die", t11_c4: "es",
    t11_q: "Was muss auf einen starken Interjektion (Endung „!“) folgen?",
    t11_qc1: "Ein Großbuchstabe", t11_qc2: "Ein Komma", t11_qc3: "Ein Kleinbuchstabe", t11_qc4: "Ein Semikolon",
    t11_svg_p1: "Wow!", t11_svg_p2: "Es ist groß.",

    // T12 - Interjections in Dialogue
    t12_title: "Interjektionen in Zitaten",
    t12_text: "Interjektionen kommen im gesprochenen Dialog sehr häufig vor. „Ups, ich habe es fallen lassen“, sagte Tim.“",
    t12_inst: "Bilden Sie den Dialogsatz!",
    t12_h1: "Beginnen Sie mit den Anführungszeichen.",
    t12_h2: "„Wow, das ist riesig“, sagte sie.",
    t12_p1: "„Wow,", t12_p2: "das heißt", t12_p3: "riesig“,", t12_p4: "sagte sie.",
    t12_q: "Wo finden wir Interjektionen am häufigsten?",
    t12_c1: "Im gesprochenen Dialog", t12_c2: "In formellen Aufsätzen", t12_c3: "In Wissenschaftsberichten", t12_c4: "In juristischen Dokumenten",
    t12_svg_w1: "Dialog",

    // T13 - Formal vs Informal
    t13_title: "Formell vs. informell",
    t13_text: "Die meisten Interjektionen sind informell. Du würdest nicht „Igitt!“ schreiben. in einem wissenschaftlichen Aufsatz. Einige, wie „Alas“, sind formell und altmodisch.",
    t13_inst: "Sortieren Sie die Einwürfe nach Formalität!",
    t13_h1: "„Alas“ und „Indeed“ sind formal. „Yuck“ ist informell.",
    t13_h2: "Setzen Sie „Yay“ auf „Informell“.",
    t13_i1: "Leider", t13_i2: "Tatsächlich", t13_i3: "Igitt", t13_i4: "Ja",
    t13_b1: "Formal / Alt", t13_b2: "Informell",
    t13_q: "Welcher Interjektion gilt als förmlich und altmodisch?",
    t13_c1: "Leider", t13_c2: "Ja", t13_c3: "Ups", t13_c4: "Ew",
    t13_svg_l1: "Formell", t13_svg_r1: "Informell",

    // T14 - Choosing the Right Interjection
