    t1_c1: "Hűha", t1_c2: "És", t1_c3: "A", t1_c4: "Fuss",
    t1_q: "Az alábbiak közül melyik közbeszólás?",
    t1_svg_1: "Hűha", t1_svg_2: "Jaj",

    // T2 - Strong Interjections (!)
    t2_title: "Erős közbeszólások",
    t2_text: "Az erős közbeszólások intenzív érzelmet mutatnak, és általában felkiáltójel (!) követi őket. Példa: 'Jaj! Ez fájt.",
    t2_inst: "Emelje ki az erős közbeszólást!",
    t2_h1: "Keresse meg a szót közvetlenül a felkiáltójel előtt.",
    t2_h2: "A szó „Hurrá”.",
    t2_sent: "Hurrá! Megnyertük a bajnoki mérkőzést.",
    t2_target: "Hurrá!",
    t2_q: "Milyen írásjelek követik általában az erős közbeszólást?",
    t2_c1: "felkiáltójel (!)", t2_c2: "vessző (,)", t2_c3: "időszak (.)", t2_c4: "kérdőjel (?)",
    t2_svg_icon: "!", t2_svg_lbl: "Erős érzelem",

    // T3 - Mild Interjections (,)
    t3_title: "Enyhe közbeszólások",
    t3_text: "Az enyhe közbeszólások kevesebb érzelmet mutatnak, és vessző követi őket. Példa: \"Nos, azt hiszem, most már mehetünk.\"",
    t3_inst: "Emelje ki az enyhe közbeszólást!",
    t3_h1: "Keresse a szót a vessző előtt az elején.",
