    t3_target: "Ó,",
    t3_q: "Milyen írásjelek követik az enyhe közbeszólást?",
    t3_c1: "vessző (,)", t3_c2: "felkiáltójel (!)", t3_c3: "pontosvessző (;)", t3_c4: "kettőspont (:)",
    t3_svg_icon: ",", t3_svg_lbl: "Enyhe érzelem",

    // T4 - "Wow" (Surprise)
    t4_title: "Meglepetés megjelenítése",
    t4_text: "Olyan közbeszólásokat használunk, mint a „Wow”, „Hú” vagy „Oh”, hogy kifejezzük a meglepetést vagy a csodálkozást.",
    t4_inst: "Párosítsd a közbeszólást az érzéséhez!",
    t4_h1: "A „Wow” meglepetéssel illik.",
