    t4_c1: "Hűha!", t4_c2: "Jaj!", t4_c3: "Ugh!", t4_c4: "Hoppá!",
    t4_svg_w1: "Hűha!",

    // T5 - "Oops" (Mistake)
    t5_title: "Hoppá! Hibázás",
