    t5_c1: "Hoppá", t5_c2: "Hurrá", t5_c3: "Jaj", t5_c4: "Fú",
    t5_q: "Melyik közbeszólást használjuk, ha kis hibát követünk el?",
    t5_svg_w1: "Hoppá!",

    // T6 - "Hey" (Greeting)
    t6_title: "Üdvözlet közbeszólásként",
    t6_text: "Az olyan szavak, mint a „Szia”, „Szia” és „Hello” közbeszólásként működhetnek, ha valaki figyelmét felkeltik velük.",
