    t1_text: "A pontosvessző két egymáshoz szorosan kapcsolódó független tagmondat összekapcsolására szolgál kötőszó használata nélkül (például „és” vagy „de”). – Esett az eső; mi bent maradtunk.",
    t1_inst: "Töltsd ki az üres részt pontosvesszővel!",
    t1_h1: "Keresse meg azt a szimbólumot, amely vesszőnek tűnik, felette egy ponttal.",
    t1_h2: "Használja a ';'-t.",
    t1_sent: "A kutyám barátságos ___ a macskám félénk.",
    t1_c1: ";", t1_c2: ",", t1_c3: ":", t1_c4: "-",
    t1_q: "Mit köt össze a pontosvessző?",
    t1_qc1: "Két kapcsolódó független tagmondat", t1_qc2: "Egy függő és egy független záradék", t1_qc3: "Egy főnév és egy ige", t1_qc4: "Elemek egy egyszerű listában",
    t1_svg_w1: ";",

    // T2 - Colon (Lists)
