    t2_h1: "Keresse meg a szimbólumot két egymásra helyezett ponttal.",
    t2_h2: "Jelölje ki a ':' elemet.",
    t2_sent: "Szükségem van: tollakra, papírra és ragasztószalagra.",
    t2_target: ":",
    t2_q: "Melyik írásjelet használjuk a lista bevezetéséhez?",
    t2_c1: "kettőspont (:)", t2_c2: "pontosvessző (;)", t2_c3: "vessző (,)", t2_c4: "kötőjel (-)",
    t2_svg_w1: ":",

    // T3 - Apostrophe (Contractions)
    t3_title: "Aposztrófok: Összehúzódások",
    t3_text: "Az aposztróf azt mutatja, hogy hol hagytak ki betűket az összehúzódásból. A „ne”-ből „ne” lesz. Az „ők”-ből „ők” lesz.",
    t3_inst: "Kösd össze a szavakat az összehúzódásukkal!",
    t3_h1: "nem lehet = nem lehet. ez = ez.",
    t3_h2: "A „nem” és a „nem” egyezése.",
    t3_l1: "nem lehet", t3_r1: "nem lehet",
    t3_l2: "ez van", t3_r2: "ez van",
    t3_l3: "nem", t3_r3: "nem",
    t3_q: "Mit jelent az aposztróf az 'ez'-ben?",
    t3_qc1: "A hiányzó „i” betű az „is”-ből", t3_qc2: "Tulajdonjog", t3_qc3: "Többes számú főnév", t3_qc4: "Szünet",
    t3_svg_w1: "'",

    // T4 - Apostrophe (Singular Possessive)
    t4_title: "Aposztrófok: Egyes szám birtokos",
    t4_text: "Annak kimutatásához, hogy EGY személy vagy dolog birtokol valamit, adjon hozzá egy aposztrófot és egy „s”-t ('s). „A kutya csontja” = a kutyához tartozó csont.",
    t4_inst: "Építsd fel a birtokos kifejezést!",
    t4_h1: "A fiúhoz tartozó játék.",
    t4_h2: "A fiú játékszere.",
    t4_w1: "A", t4_w2: "fiúé", t4_w3: "játékszer",
    t4_q: "Hogyan lehet az egyes számú főnevet birtokossá tenni?",
    t4_c1: "Add hozzá", t4_c2: "add hozzá", t4_c3: "Add s", t4_c4: "Add es",
    t4_svg_w1: "'s",

    // T5 - Apostrophe (Plural Possessive)
