    t5_text: "Ha egy többes számú főnév már „s”-re végződik, csak írjon egy aposztrófot az „s” (s) után a tulajdonjog jelzésére. „A kutyák csontjai” = több kutyához tartozó csontok.",
    t5_inst: "Válaszd ki a megfelelő többes szám birtokjelet!",
    t5_h1: "A terem több tanáré.",
    t5_h2: "A tanári szoba.",
    t5_sent: "Ez a ___ szoba. (sok tanáré)",
    t5_c1: "tanárok", t5_c2: "tanári", t5_c3: "tanárok", t5_c4: "tanár",
