    t5_qc1: "Adjon aposztrófot az s (macskák) után", t5_qc2: "Add 's (macskák)", t5_qc3: "Ne adjunk hozzá semmit", t5_qc4: "Add es' (macskák)",
    t5_svg_w1: "s'",

    // T6 - its vs it's
