    t6_h1: "Ez = az. Annak = hozzátartozója.",
    t6_h2: "Tedd az \"it's\" szót a kontrakcióba.",
    t6_b1: "Összehúzódás (van) ✂️", t6_b2: "Birtokos (Tulajdonjog) 🐾",
    t6_i1: "Hideg van.", t6_i2: "Az enyém.", t6_i3: "A farka.", t6_i4: "Az étele.",
