    t7_qc1: "te vagy", t7_qc2: "hozzád tartozó", t7_qc3: "fogsz", t7_qc4: "megvan",
    t7_svg_l1: "te vagy", t7_svg_r1: "a te",

    // T8 - their vs they're vs there
    t8_title: "Az övék, Ők, ott vannak",
