    t8_l1: "Ők", t8_r1: "Ők azok",
    t8_l2: "Az övék", t8_r2: "Hozzájuk tartozik",
    t8_l3: "Ott", t8_r3: "Azon a helyen",
    t8_q: "Melyik szó jelöl egy helyet?",
    t8_c1: "ott", t8_c2: "az övék", t8_c3: "ők", t8_c4: "az övék",
    t8_svg_w1: "ők / az övék / ott vannak",

