    // T10 - Hyphen (Compound Adjectives)
    t10_title: "A kötőjel: Melléknevek",
    t10_text: "Használjon kötőjelet két szó összekapcsolására, amelyek EGY melléknévként működnek együtt egy főnév előtt. – Ő egy jól ismert színész.",
