    t10_svg_lbl: "Melléknevek",

    // T11 - Semicolon with Conjunctive Adverbs
    t11_title: "Pontosvessző és azonban",
    t11_text: "Használjon pontosvesszőt az olyan szavak előtt, mint a „bár” vagy „ezért”, amikor két független tagmondatot kapcsolnak össze. Kövesse őket vesszővel. – Fáradt voltam; azonban befejeztem a versenyt.",
