    t14_c1: "spannend", t14_c2: "langweilig", t14_c3: "kurz", t14_c4: "verwirrend",
    t14_q: "Was ist der Hauptzweck der Verwendung bildlicher Sprache?",
    t14_qc1: "Um lebendige Bilder und Emotionen zu erzeugen", t14_qc2: "Um schneller zu schreiben", t14_qc3: "Um genaue, wörtliche Fakten zu liefern", t14_qc4: "Um die Verwendung von Adjektiven zu vermeiden",
    t14_svg_w1: "Effekte",

    // T15 - Mixed Review
